import argparse
import csv
from collections import defaultdict, deque
from pathlib import Path


# ============================================================
# Green DISTRI Activity Metrics
#
# Input:
#   activity_events.csv generated by ActivityObserver
#
# Current observed events:
#   COMPUTE_START
#   COMPUTE_END
#
# Outputs:
#   compute_attempt_intervals.csv
#   processor_activity_metrics.csv
#   site_activity_summary.csv
#
# Important:
#   One Job may execute more than once because of
#   failure/recovery/reassignment behavior in DISTRI.
# ============================================================


def union_duration(intervals):
    """
    Calculate unique processor busy time.

    Overlapping compute intervals are merged.

    Example:
        Job A: 10 -> 20
        Job B: 15 -> 25

    Sum of job compute durations = 20 s
    Unique processor busy time   = 15 s
    """

    if not intervals:
        return 0.0

    ordered = sorted(
        (
            interval["start_time"],
            interval["end_time"],
        )
        for interval in intervals
    )

    current_start, current_end = ordered[0]

    total = 0.0

    for start, end in ordered[1:]:

        if start <= current_end:
            current_end = max(
                current_end,
                end,
            )

        else:
            total += (
                current_end
                - current_start
            )

            current_start = start
            current_end = end

    total += (
        current_end
        - current_start
    )

    return total


def peak_concurrency(intervals):
    """
    Calculate maximum number of simultaneously active
    compute attempts on a processor.

    End events are processed before start events if both
    occur at exactly the same simulation time.
    """

    timeline = []

    for interval in intervals:

        timeline.append(
            (
                interval["start_time"],
                1,
            )
        )

        timeline.append(
            (
                interval["end_time"],
                -1,
            )
        )

    # -1 sorts before +1 at identical timestamps.
    timeline.sort(
        key=lambda event: (
            event[0],
            event[1],
        )
    )

    active = 0
    peak = 0

    for _, delta in timeline:

        active += delta

        peak = max(
            peak,
            active,
        )

    return peak


def read_compute_intervals(
    events_path,
    simulation_time,
):
    """
    Reconstruct compute execution intervals from:

        COMPUTE_START
        COMPUTE_END

    Multiple execution attempts of the same Job are allowed.

    FIFO pairing is used:

        START attempt 1
        START attempt 2
        END attempt 1
        END attempt 2

    Jobs still running when the simulation stops are clipped
    at simulation_time and marked as right-censored.
    """

    # key:
    #   (site_id, processor_id, job_id)
    #
    # value:
    #   queue of (start_time, attempt_id)
    starts = defaultdict(deque)

    # Count execution attempts separately for each
    # Job/Processor combination.
    attempt_counter = defaultdict(int)

    intervals = []

    events_path = Path(events_path)

    with events_path.open(
        "r",
        newline="",
    ) as csvfile:

        reader = csv.DictReader(
            csvfile
        )

        required_columns = {
            "sim_time",
            "event",
            "site_id",
            "processor_id",
            "job_id",
            "job_category",
            "computation",
            "data_volume",
        }

        if reader.fieldnames is None:
            raise ValueError(
                "activity_events.csv has no header."
            )

        missing = (
            required_columns
            - set(reader.fieldnames)
        )

        if missing:
            raise ValueError(
                "activity_events.csv is missing "
                f"required columns: {sorted(missing)}"
            )

        for row in reader:

            event = row["event"]

            if event not in {
                "COMPUTE_START",
                "COMPUTE_END",
            }:
                continue

            sim_time = float(
                row["sim_time"]
            )

            site_id = int(
                row["site_id"]
            )

            processor_id = int(
                row["processor_id"]
            )

            job_id = int(
                row["job_id"]
            )

            job_category = int(
                row["job_category"]
            )

            computation = float(
                row["computation"]
            )

            data_volume = float(
                row["data_volume"]
            )

            key = (
                site_id,
                processor_id,
                job_id,
            )

            # ------------------------------------------------
            # COMPUTE START
            # ------------------------------------------------

            if event == "COMPUTE_START":

                attempt_counter[key] += 1

                attempt_id = (
                    attempt_counter[key]
                )

                starts[key].append(
                    {
                        "start_time":
                            sim_time,
                        "attempt_id":
                            attempt_id,
                        "job_category":
                            job_category,
                        "computation":
                            computation,
                        "data_volume":
                            data_volume,
                    }
                )

            # ------------------------------------------------
            # COMPUTE END
            # ------------------------------------------------

            elif event == "COMPUTE_END":

                if (
                    key not in starts
                    or not starts[key]
                ):
                    raise ValueError(
                        "COMPUTE_END without "
                        "matching COMPUTE_START "
                        f"for {key} at "
                        f"time {sim_time}"
                    )

                start_record = (
                    starts[key].popleft()
                )

                start_time = (
                    start_record[
                        "start_time"
                    ]
                )

                end_time = min(
                    sim_time,
                    simulation_time,
                )

                if end_time < start_time:
                    raise ValueError(
                        "Invalid compute interval "
                        f"for {key}: "
                        f"{start_time} -> "
                        f"{end_time}"
                    )

                duration = (
                    end_time
                    - start_time
                )

                intervals.append(
                    {
                        "site_id":
                            site_id,
                        "processor_id":
                            processor_id,
                        "job_id":
                            job_id,
                        "attempt_id":
                            start_record[
                                "attempt_id"
                            ],
                        "job_category":
                            start_record[
                                "job_category"
                            ],
                        "computation":
                            start_record[
                                "computation"
                            ],
                        "data_volume":
                            start_record[
                                "data_volume"
                            ],
                        "start_time":
                            start_time,
                        "end_time":
                            end_time,
                        "duration":
                            duration,
                        "censored":
                            False,
                    }
                )

                if not starts[key]:
                    del starts[key]

    # ========================================================
    # RIGHT-CENSORED EXECUTIONS
    #
    # These are Jobs that started computing but did not
    # finish before simulation_time.
    # ========================================================

    for key, start_queue in starts.items():

        site_id, processor_id, job_id = key

        for start_record in start_queue:

            start_time = (
                start_record[
                    "start_time"
                ]
            )

            if start_time >= simulation_time:
                continue

            end_time = simulation_time

            duration = (
                end_time
                - start_time
            )

            intervals.append(
                {
                    "site_id":
                        site_id,
                    "processor_id":
                        processor_id,
                    "job_id":
                        job_id,
                    "attempt_id":
                        start_record[
                            "attempt_id"
                        ],
                    "job_category":
                        start_record[
                            "job_category"
                        ],
                    "computation":
                        start_record[
                            "computation"
                        ],
                    "data_volume":
                        start_record[
                            "data_volume"
                        ],
                    "start_time":
                        start_time,
                    "end_time":
                        end_time,
                    "duration":
                        duration,
                    "censored":
                        True,
                }
            )

    intervals.sort(
        key=lambda row: (
            row["site_id"],
            row["processor_id"],
            row["start_time"],
            row["job_id"],
            row["attempt_id"],
        )
    )

    return intervals


def derive_metrics(
    events_path,
    simulation_time,
    num_processors,
    output_dir,
    site_id=0,
):
    """
    Derive processor-level and site-level activity metrics.
    """

    intervals = read_compute_intervals(
        events_path=events_path,
        simulation_time=simulation_time,
    )

    intervals_by_processor = defaultdict(
        list
    )

    for interval in intervals:

        processor_key = (
            interval["site_id"],
            interval["processor_id"],
        )

        intervals_by_processor[
            processor_key
        ].append(
            interval
        )

    processor_rows = []

    total_busy_seconds = 0.0
    total_job_compute_seconds = 0.0

    total_completed_attempts = 0
    total_censored_attempts = 0

    all_unique_jobs = set()

    # ========================================================
    # PROCESSOR METRICS
    #
    # Include every processor even if it did no compute work.
    #
    # Current MVP assumes one site and processor IDs:
    #   0 .. num_processors-1
    # ========================================================

    for processor_id in range(
        num_processors
    ):

        key = (
            site_id,
            processor_id,
        )

        processor_intervals = (
            intervals_by_processor.get(
                key,
                [],
            )
        )

        job_compute_seconds = sum(
            interval["duration"]
            for interval
            in processor_intervals
        )

        busy_seconds = union_duration(
            processor_intervals
        )

        overlap_compute_seconds = max(
            0.0,
            job_compute_seconds
            - busy_seconds,
        )

        activity_ratio = (
            busy_seconds
            / simulation_time
            if simulation_time > 0
            else 0.0
        )

        average_concurrent_jobs = (
            job_compute_seconds
            / simulation_time
            if simulation_time > 0
            else 0.0
        )

        peak = peak_concurrency(
            processor_intervals
        )

        unique_jobs = {
            interval["job_id"]
            for interval
            in processor_intervals
        }

        compute_attempts = len(
            processor_intervals
        )

        additional_attempts = max(
            0,
            compute_attempts
            - len(unique_jobs),
        )

        completed_attempts = sum(
            1
            for interval
            in processor_intervals
            if not interval[
                "censored"
            ]
        )

        censored_attempts = sum(
            1
            for interval
            in processor_intervals
            if interval[
                "censored"
            ]
        )

        mean_attempt_duration = (
            job_compute_seconds
            / compute_attempts
            if compute_attempts > 0
            else 0.0
        )

        processor_rows.append(
            {
                "site_id":
                    site_id,
                "processor_id":
                    processor_id,

                "unique_jobs":
                    len(unique_jobs),

                "compute_attempts":
                    compute_attempts,

                "additional_attempts":
                    additional_attempts,

                "completed_compute_attempts":
                    completed_attempts,

                "censored_compute_attempts":
                    censored_attempts,

                "job_compute_seconds":
                    job_compute_seconds,

                "busy_seconds":
                    busy_seconds,

                "overlap_compute_seconds":
                    overlap_compute_seconds,

                "activity_ratio":
                    activity_ratio,

                "activity_percent":
                    activity_ratio * 100.0,

                "average_concurrent_jobs":
                    average_concurrent_jobs,

                "peak_concurrent_jobs":
                    peak,

                "mean_attempt_duration":
                    mean_attempt_duration,
            }
        )

        total_busy_seconds += (
            busy_seconds
        )

        total_job_compute_seconds += (
            job_compute_seconds
        )

        total_completed_attempts += (
            completed_attempts
        )

        total_censored_attempts += (
            censored_attempts
        )

        all_unique_jobs.update(
            unique_jobs
        )

    # ========================================================
    # SITE METRICS
    # ========================================================

    available_processor_seconds = (
        num_processors
        * simulation_time
    )

    site_activity_ratio = (
        total_busy_seconds
        / available_processor_seconds
        if available_processor_seconds > 0
        else 0.0
    )

    total_compute_attempts = len(
        intervals
    )

    additional_attempts = max(
        0,
        total_compute_attempts
        - len(all_unique_jobs),
    )

    total_overlap_compute_seconds = max(
        0.0,
        total_job_compute_seconds
        - total_busy_seconds,
    )

    average_concurrent_compute = (
        total_job_compute_seconds
        / available_processor_seconds
        if available_processor_seconds > 0
        else 0.0
    )

    site_summary = {
        "site_id":
            site_id,

        "simulation_time":
            simulation_time,

        "num_processors":
            num_processors,

        "available_processor_seconds":
            available_processor_seconds,

        "unique_jobs_observed":
            len(all_unique_jobs),

        "compute_attempts":
            total_compute_attempts,

        "additional_attempts":
            additional_attempts,

        "completed_compute_attempts":
            total_completed_attempts,

        "censored_compute_attempts":
            total_censored_attempts,

        "total_job_compute_seconds":
            total_job_compute_seconds,

        "total_processor_busy_seconds":
            total_busy_seconds,

        "total_overlap_compute_seconds":
            total_overlap_compute_seconds,

        "site_activity_ratio":
            site_activity_ratio,

        "site_activity_percent":
            site_activity_ratio
            * 100.0,

        "normalized_average_concurrent_compute":
            average_concurrent_compute,
    }

    # ========================================================
    # WRITE OUTPUTS
    # ========================================================

    output_dir = Path(
        output_dir
    )

    output_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    # --------------------------------------------------------
    # 1. Raw reconstructed compute attempts
    # --------------------------------------------------------

    attempts_output = (
        output_dir
        / "compute_attempt_intervals.csv"
    )

    with attempts_output.open(
        "w",
        newline="",
    ) as csvfile:

        attempt_fieldnames = [
            "site_id",
            "processor_id",
            "job_id",
            "attempt_id",
            "job_category",
            "computation",
            "data_volume",
            "start_time",
            "end_time",
            "duration",
            "censored",
        ]

        writer = csv.DictWriter(
            csvfile,
            fieldnames=
                attempt_fieldnames,
        )

        writer.writeheader()

        writer.writerows(
            intervals
        )

    # --------------------------------------------------------
    # 2. Processor metrics
    # --------------------------------------------------------

    processor_output = (
        output_dir
        / "processor_activity_metrics.csv"
    )

    with processor_output.open(
        "w",
        newline="",
    ) as csvfile:

        writer = csv.DictWriter(
            csvfile,
            fieldnames=
                processor_rows[0].keys(),
        )

        writer.writeheader()

        writer.writerows(
            processor_rows
        )

    # --------------------------------------------------------
    # 3. Site summary
    # --------------------------------------------------------

    site_output = (
        output_dir
        / "site_activity_summary.csv"
    )

    with site_output.open(
        "w",
        newline="",
    ) as csvfile:

        writer = csv.DictWriter(
            csvfile,
            fieldnames=
                site_summary.keys(),
        )

        writer.writeheader()

        writer.writerow(
            site_summary
        )

    return (
        intervals,
        processor_rows,
        site_summary,
    )


def main():

    parser = argparse.ArgumentParser(
        description=(
            "Derive Green DISTRI "
            "compute activity metrics "
            "from ActivityObserver events."
        )
    )

    parser.add_argument(
        "--events",
        required=True,
        help=(
            "Path to "
            "activity_events.csv"
        ),
    )

    parser.add_argument(
        "--simulation-time",
        type=float,
        required=True,
        help=(
            "Total simulated duration "
            "in seconds."
        ),
    )

    parser.add_argument(
        "--num-processors",
        type=int,
        required=True,
        help=(
            "Number of processors "
            "in the simulated site."
        ),
    )

    parser.add_argument(
        "--site-id",
        type=int,
        default=0,
        help=(
            "Site ID for this MVP "
            "single-site analysis. "
            "Default: 0"
        ),
    )

    parser.add_argument(
        "--output-dir",
        required=True,
        help=(
            "Directory for generated "
            "GDCS metrics CSV files."
        ),
    )

    args = parser.parse_args()

    (
        intervals,
        processor_rows,
        site,
    ) = derive_metrics(
        events_path=
            args.events,
        simulation_time=
            args.simulation_time,
        num_processors=
            args.num_processors,
        output_dir=
            args.output_dir,
        site_id=
            args.site_id,
    )

    print()
    print(
        "Green DISTRI Compute "
        "Activity Metrics"
    )
    print("=" * 72)

    for row in processor_rows:

        print(
            f"Site "
            f"{row['site_id']} | "
            f"Processor "
            f"{row['processor_id']}: "
            f"{row['busy_seconds']:.4f} "
            f"busy s | "
            f"{row['activity_percent']:.2f}% "
            f"activity | "
            f"{row['compute_attempts']} "
            f"attempt(s) | "
            f"{row['unique_jobs']} "
            f"unique job(s) | "
            f"peak concurrency "
            f"{row['peak_concurrent_jobs']}"
        )

    print("-" * 72)

    print(
        "Unique jobs observed: "
        f"{site['unique_jobs_observed']}"
    )

    print(
        "Compute attempts: "
        f"{site['compute_attempts']}"
    )

    print(
        "Additional/re-execution "
        "attempts: "
        f"{site['additional_attempts']}"
    )

    print(
        "Completed compute attempts: "
        f"{site['completed_compute_attempts']}"
    )

    print(
        "Right-censored attempts: "
        f"{site['censored_compute_attempts']}"
    )

    print(
        "Total job-compute time: "
        f"{site['total_job_compute_seconds']:.4f} s"
    )

    print(
        "Total processor busy time: "
        f"{site['total_processor_busy_seconds']:.4f} s"
    )

    print(
        "Overlapping compute time: "
        f"{site['total_overlap_compute_seconds']:.4f} s"
    )

    print(
        "Available processor time: "
        f"{site['available_processor_seconds']:.4f} s"
    )

    print(
        "Site compute activity ratio: "
        f"{site['site_activity_percent']:.2f}%"
    )

    print("=" * 72)

    print(
        "\nGenerated:"
    )

    print(
        "  compute_attempt_intervals.csv"
    )

    print(
        "  processor_activity_metrics.csv"
    )

    print(
        "  site_activity_summary.csv"
    )


if __name__ == "__main__":
    main()